            printf("   ");
        }

        for (int j = 0; j < 12; j++)
        {
            if ((i > 0 && i < 11) && (j > 0 && j < 11))
            {
                logic = mat[i - 1][j - 1];
                imp = printTable(logic, stage);
                printf("%c", imp);
            }
            else
            {
                printf("#");
            }

            if (j < 11)
            {
                printf(" ");
            }
        }
        printf("\n");
    }
}

